  const generatorKey = toGeneratorOnlyKey({ generatorId: zodEntry.id });

  switch (schema.type) {
    case "custom":
      return schema;
    case "ref":
      return new ZodRef({
        context,
        destinationPath,
        refName: toRefName(schema.$ref),
        modifiers,
        rootRef,
        schema,
      });
    case "array":
      return new ZodArray({
        context,
        destinationPath,
        modifiers,
        items: schema.items,
        generatorKey,
        rootRef,
        schema,
      });
    case "object":
