        context,
        destinationPath,
        objectSchema: schema,
        modifiers,
        generatorKey,
        rootRef,
      });
    case "union":
      return new ZodUnion({
        context,
        destinationPath,
        members: schema.members,
        discriminator: schema.discriminator,
        modifiers,
        generatorKey,
        rootRef,
        schema,
      });
    case "number":
      return new ZodNumber({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
      });
    case "integer":
