import { TsSnippet } from "jsr:@skmtc/lang-typescript@0.12.17";
import type { GenerateContextType, GeneratorKey, Modifiers, OasRef, OasSchema, RefName, TypeSystemValue } from 'jsr:@skmtc/core@0.28.3'
import { toZodValue } from "./Zod.ts";
import { applyModifiers } from "./applyModifiers.ts";

type ZodArrayArgs = {
  context: GenerateContextType;
  destinationPath: string;
  items: OasSchema | OasRef<"schema">;
  /** The originating array schema node — for fine-grained attribution. */
  schema?: OasSchema | OasRef<"schema">;
  modifiers: Modifiers;
  generatorKey: GeneratorKey;
  rootRef?: RefName;
};

export class ZodArray extends TsSnippet {
  type = "array" as const;
  items: TypeSystemValue;
  modifiers: Modifiers;

  constructor(
    { context, generatorKey, destinationPath, items, modifiers, rootRef, schema }:
      ZodArrayArgs,
  ) {
    super({ context, generatorKey, stackTrail: schema?.stackTrail.clone() });

    this.modifiers = modifiers;

    this.items = toZodValue({
      destinationPath,
      schema: items,
      required: true,
      context,
      rootRef,
    });

    this.register({ imports: { zod: ["z"] }, destinationPath });
  }

  override toString(): string {
    return applyModifiers(`z.array(${this.items})`, this.modifiers);
  }
}

